  final graph = Graph();

  for (int i = 0; i < a.length - 1; i++) {
    final nodeA = Node(a[i]);
    final nodeB = Node(a[i + 1]);

    // Add nodes to the graph
    graph.addNode(nodeA);
    graph.addNode(nodeB);

    // Create an edge between them, assuming unweighted and undirected
    graph.addEdge(nodeA, nodeB);
  }

  // Find all possible paths of length >= 3 in the graph
  List<List<Node>> allPaths = [];

  void dfs(Node current, List<Node> path, Set<Node> visited) {
    if (path.length > 2 && !visited.contains(current)) {
      // Make sure we don't revisit nodes when creating longer paths
      var newVisited = {...visited};
      newVisited.add(current);

      // Check if this is a valid cycle or just a sequence with at least three unique characters
      bool isValidPath = true;
      for (var node in path) {
        if (node == current && path.indexOf(node) != path.lastIndexOf(node)) {
          isValidPath = false;
          break;
        }
      }

      if (isValidPath) {
        allPaths.add([...path, current]);
      }
    }

    // If the path has less than 3 elements, continue exploring
    if (path.length < 3) {
      for (final neighbor in graph.getNeighbors(current)) {
        dfs(neighbor, [...path, current], visited);
      }
    }
  }

  // Start DFS from each node
  for (final node in graph.nodes) {
    dfs(node, [], {Node.empty()});
  }

  // Convert paths into string representations
  return allPaths.map((path) => path.map((n) => n.value).join()).toList();
}
