import 'dart:math';

class Solution {
  static double calculateSumProductAndCountOddIntegers(List<double> numbers) {
    // Check if the list is empty or has only one element, in which case return 0
    if (numbers.isEmpty || numbers.length == 1) {
      return 0.0;
    }

    // Initialize variables to store the sum of products and the count of odd integers
    double sumProducts = 0.0;
    int oddIntegerCount = 0;

    // Iterate through the list to calculate the sum of adjacent products
    for (int i = 0; i < numbers.length - 1; i++) {
      sumProducts += numbers[i] * numbers[i + 1];
    }

    // Count how many elements are positive odd integers
    for (double number in numbers) {
      if (number > 0 && number.isFinite && !number.isNaN && number.toInt() == number && number % 2 == 1) {
        oddIntegerCount++;
      }
    }

    // Calculate the result by dividing the sum of products by the count of odd integers
    // Handle division by zero case to avoid runtime errors
    if (oddIntegerCount == 0) {
      throw Exception("No valid odd integers found in the list.");
    }

    return (sumProducts / oddIntegerCount).ceil();
  }
}

void main() {
  List<double> exampleList = [3.0, 4.5, 7.0, 9.0, 11.0]; // Example input data
  try {
    var result = Solution.calculateSumProductAndCountOddIntegers(exampleList);
    print('Result: $result');
  } catch (e) {
    print('Error: $e');
  }
}
