class UnicodeScalar {
  static const int min = 0x0000;
  static const int max = 0x10FFFF;

  final int _value;

  const UnicodeScalar(this._value);

  factory UnicodeScalar.fromValue(int value) {
    assert(value >= min && value <= max, 'Invalid Unicode scalar value');
    return new UnicodeScalar(value);
  }

  bool get isValid => _value >= min && _value <= max;

  @override
  String toString() => '$runtimeType(${_value.toRadixString(16)})';

  void toUTF16(List<int> buffer) {
    if (_value < 0x10000) {
      buffer.add(_value & 0xFF);
    } else {
      int offset = _value - 0x10000;
      int highSurrogate = (offset >> 10) + 0xD800;
      int lowSurrogate = (offset & 0x3FF) + 0xDC00;

      buffer.add(highSurrogate & 0xFF);
      buffer.add(lowSurrogate & 0xFF);
    }
  }
}

