// Function to find all unique substrings with specific conditions
List<String> findSubstringsWithConditions(String input) {
  List<String> result = [];

  for (var i = 0; i < input.length; i++) {
    var substringStart = i;
    while (substringStart < input.length) {
      var substringEnd = substringStart + 1;

      // Ensure we don't go out of bounds
      if (substringEnd > input.length) break;

      // Get current and next substring
      var currSubstring = input.substring(substringStart, substringEnd);
      var nextSubstring = input.substring(substringEnd, substringEnd + 1);

      // If both substrings exist, perform checks
      if (nextSubstring.isNotEmpty) {
        // Check if they share at least one common character
        if (hasCommonChar(currSubstring, nextSubstring)) {
          // Add valid substring pair to results
          result.add(currSubstring + nextSubstring);

          // Move to next start position after this substring
          substringStart = substringEnd + 1;
          break;
        } else {
          // No match found, move to next possible position
          substringStart++;
        }
      } else {
        // End of string reached, stop processing further
        break;
      }
    }
  }

  return result;
}

